adj = [set() for _ in range(n)]
for i in range(n):
    for j in range(i + 1, n):
        if is_close(perms[i], perms[j]):
            adj[i].add(j)
            adj[j].add(i)

visited = [False] * n
for i in range(n):
    if not visited[i]:
        comp = []
        stack = [i]
        visited[i] = True
        while stack:
            u = stack.pop()
            comp.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        print(f"Component size: {len(comp)}")
